# ============================================================================
#  DataUsageTracker v1.0.2 - SELF-CONTAINED Windows installer
#  Code embedded - fully offline after download.
#  One-line install (PowerShell):  iwr -useb <release-asset-url>/install-windows.ps1 | iex
#  One-line install (CMD):         powershell -NoProfile -ExecutionPolicy Bypass -Command "iwr -useb <release-asset-url>/install-windows.ps1 | iex"
#  Modes: install (default) | -Status | -Uninstall
# ============================================================================
[CmdletBinding()]
param(
    [string]$InstallDir = "$env:USERPROFILE\DataUsageTracker",
    [switch]$Uninstall,
    [switch]$Status,
    [switch]$Quiet
)
$ErrorActionPreference = 'Stop'
$TaskName = "DataUsageTracker"
$LogDir = Join-Path $env:USERPROFILE "DataUsageLogs"

if ($Status) {
    Write-Host "=== DataUsage Tracker status ==="
    try { Get-ScheduledTask -TaskName $TaskName -ErrorAction Stop | Format-List TaskName, State } 
    catch { Write-Host "Scheduled task not registered." }
    if (Test-Path (Join-Path $LogDir "DataUsage_Log.csv")) {
        $rows = (Get-Content (Join-Path $LogDir "DataUsage_Log.csv") | Measure-Object -Line).Lines - 1
        Write-Host "Log rows: $rows  in $LogDir"
    } else { Write-Host "No logs yet." }
    exit 0
}

if ($Uninstall) {
    if (Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue) {
        Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false
        Write-Host "Scheduled task removed."
    }
    if (Test-Path $InstallDir) { Remove-Item -Recurse -Force $InstallDir }
    Write-Host "Uninstalled. Logs kept in $LogDir (delete manually to purge)."
    exit 0
}

Write-Host "[DataUsageTracker] Installing (self-contained, offline) to $InstallDir ..."
New-Item -ItemType Directory -Path $InstallDir -Force | Out-Null
New-Item -ItemType Directory -Path $LogDir -Force | Out-Null

# --- decode embedded payloads ------------------------------------------------
$trackerB64 = @"

"@
[IO.File]::WriteAllBytes((Join-Path $InstallDir "DataUsageTracker.ps1"), [Convert]::FromBase64String($trackerB64))

$dashB64 = @"

"@
New-Item -ItemType Directory -Path (Join-Path $InstallDir "ui") -Force | Out-Null
[IO.File]::WriteAllBytes((Join-Path $InstallDir "ui\index.html"), [Convert]::FromBase64String($dashB64))

# sanity: the main script must exist and be non-trivial before we register a task
$ScriptPath = Join-Path $InstallDir "DataUsageTracker.ps1"
if ((Test-Path $ScriptPath) -eq $false -or (Get-Item $ScriptPath).Length -lt 5000) {
    throw "[DataUsageTracker] FATAL: embedded script failed to materialize - aborting before task registration."
}

# --- scheduled task: every 30 min + at logon (low-power) ---------------------
$Action   = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$ScriptPath`" -Log -Quiet"
$TrigLogon = New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME
$TrigRep   = New-ScheduledTaskTrigger -Once -At (Get-Date) -RepetitionInterval (New-TimeSpan -Minutes 30) -RepetitionDuration (New-TimeSpan -Days 3650)
$Settings = New-ScheduledTaskSettingsSet -StartWhenAvailable -DontStopOnIdleEnd -ExecutionTimeLimit (New-TimeSpan -Minutes 3) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries
if (Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue) {
    Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false
}
Register-ScheduledTask -TaskName $TaskName -Description "Low-power Windows data usage tracker (WinRT per-app + adapter) - logs every 30 min, IST." -Action $Action -Trigger @($TrigLogon, $TrigRep) -Settings $Settings -Force | Out-Null
Start-ScheduledTask -TaskName $TaskName

$batContent = '@echo off
title Data Usage Tracker
cd /d "%~dp0"
powershell -NoProfile -ExecutionPolicy Bypass -File "%~dp0DataUsageTracker.ps1" -Snapshot
pause'
Set-Content -Path (Join-Path $InstallDir "Run-Tracker.bat") -Value $batContent

if (-not $Quiet) {
    Write-Host ""
    Write-Host "=== INSTALL COMPLETE ===" -ForegroundColor Green
    Write-Host "  Daemon:   scheduled task '$TaskName' (every 30 min + at logon)"
    Write-Host "  Logs:     $LogDir\DataUsage_Log.csv (+ per-app DataUsage_Apps.csv)"
    Write-Host "  Dashboard:$InstallDir\ui\index.html"
    Write-Host "  Status:   install-windows.ps1 -Status"
    Write-Host "  Remove:   install-windows.ps1 -Uninstall"
}
